// TH14 Extra 道中 MainSub04 C组：4×GirlC01
// 源：st07.ecl.txt:822-830（entry）、343-365（GirlC01）、367-398（GirlC01_at）
// 源 type5 BALL2 → TH14_BALL2（同号映射），色号保留源 2。

const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;

const TH14_BALL2: int = 432;

// 源 GirlC01_at：每波 6 颗（$E=5 的 do/while），共 180 波（$D=180），每波 wait(2)。
async sub girl_shot() {
    var c: int = rand(65536) - 32768;              // %C = %RANDRAD
    for wave in 0..180 {                           // $D = 180 次循环
        // circlePos(%A,%B,%C,%RANDF*64)：圆心为敌最终位置的半径≤64圆点
        var u: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;   // %RANDF
        var r64: fx = u * 64fx;
        var cx: fx = $self_x + r64 * cos(c as angle);
        var cy: fx = $self_y + r64 * sin(c as angle);
        // etOffsetAbs(A+FINAL_X, B+FINAL_Y) 固定整波出弹基点
        var a: angle = (rand(65536) - 32768) as angle;             // etAngle(0,%RANDRAD,0)
        for k in 0..6 {                                            // $E=5 → 6 次 etOn
            var offa: angle = (rand(65536) - 32768) as angle;      // etOffsetRad 随机角
            var offr: fx = ((rand(65536) - 32768) as fx / 65536 + 0.5fx) * 8fx;  // %RANDF*8
            // 出生 ANIM 退位移 position -= 4*velocity（初速1.5 → 沿角后退6px）
            var bx: fx = cx + offr * cos(offa) - 6fx * cos(a);
            var by: fx = cy + offr * sin(offa) - 6fx * sin(a);
            _ = fire(TH14_BALL2, 2, bx, by, 1.5fx, a, none, none);
        }
        // %C += π/4 + (π/2)*%RANDF
        var cu: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;  // %RANDF
        c = c + 8192 + ((16384fx * cu) as int);
        wait(2);
    }
}

// 源 GirlC01：框、速度插值、局部60帧后 async 攻击、局部260帧二次插值后常驻。
async sub girl_main() {
    set_invuln(65535);                             // 无DPS无敌外壳；源HP360保留
    set_hurtbox(12fx);                             // setHurtbox(24,24) → 24*0.5
    set_hitbox(8fx);                               // setHitbox(16,16) → 16*0.5
    move_vel(0, 90deg, 1.5fx, EASE_LINEAR);        // moveVel(π/2, 1.5)
    move_vel(80, aim_player(), 0.1fx, EASE_QUAD_IN); // moveVelTime(80,1,ANGLE_PLAYER,0.1)
    wait(60);
    spawn girl_shot();                             // @GirlC01_at() async
    wait(200);
    move_vel(80, 90deg, 1.0fx, EASE_QUAD_IN);      // moveVelTime(80,1,π/2,1.0)
    loop { wait(1000); }                           // GirlC01_404/424 常驻循环
}

// 源 MainSub04 C组：$C=2 的 2 轮，每轮左右各一只，逐次 wait(100)。
// F门：独立奖励波场景无Boss0，源F创建照常执行（不引入上游Boss）。
async sub pattern() {
    wait(OPENING_BUFFER);
    for pair in 0..2 {
        _ = spawn_enemy(-90fx, -32fx, 360, 0, 0, 0, girl_main);
        wait(100);
        _ = spawn_enemy(90fx, -32fx, 360, 0, 0, 0, girl_main);
        wait(100);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
